<?php namespace App\Http\Controllers;
use App\DentalReferral; use App\Models\ActivityLog; use App\Services\ClinicNotificationService; use App\StudentComplaint; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class DentalReferralController extends Controller {
 public function index(){return view('dental.index',['referrals'=>DentalReferral::with(['patient','complaint','nurse'])->latest()->paginate(25)]);}
 public function store(Request $r,StudentComplaint $complaint){$d=$r->validate(['triage_priority'=>'required|in:emergency,high,moderate,low','preliminary_action'=>'nullable|string|max:2000','referral_destination'=>'required|string|max:255','dental_notes'=>'nullable|string|max:2000']);abort_unless(stripos($complaint->complaint_category,'dental')!==false,422,'This concern is not categorized as Dental.');$ref=DB::transaction(function()use($r,$complaint,$d){$ref=DentalReferral::firstOrCreate(['student_complaint_id'=>$complaint->id],array_merge($d,['patient_id'=>$complaint->patient_id,'referring_nurse_id'=>$r->user()->id,'dental_concern'=>$complaint->chief_complaint,'status'=>'referred','referred_at'=>now()]));ActivityLog::create(['user_id'=>$r->user()->id,'action'=>'Dental referral created','description'=>'Dental referral #'.$ref->id]);return $ref;});return redirect()->route('dental-referrals.show',$ref)->with('success','Dental referral created.');}
 public function show(Request $r,DentalReferral $dentalReferral){$account=$r->user()->patientAccount;$staff=in_array(optional($r->user()->role)->name,['Administrator','Doctor','Nurse','Staff']);abort_unless($staff||($account&&$account->patient_id===$dentalReferral->patient_id),403);return view('dental.show',['referral'=>$dentalReferral->load(['patient','complaint','nurse'])]);}
 public function print(Request $r,DentalReferral $dentalReferral){return $this->show($r,$dentalReferral);}
}
